import{_ as o,o as e,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Declaração da Civilização Simbiótica da Âncora","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0001-锚点共生文明宣言.md","filePath":"pt/0001-锚点共生文明宣言.md"}'),t={name:"pt/0001-锚点共生文明宣言.md"};function s(d,a,n,c,l,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="declaracao-da-civilizacao-simbiotica-da-ancora" tabindex="-1">Declaração da Civilização Simbiótica da Âncora <a class="header-anchor" href="#declaracao-da-civilizacao-simbiotica-da-ancora" aria-label="Permalink to &quot;Declaração da Civilização Simbiótica da Âncora&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>01</td></tr><tr><td>Módulo</td><td>Princípios Gerais e Configuração Central</td></tr><tr><td>Palavras-chave</td><td>Declaração, Simbiose, Anti-Predação, Dez Mil Raças, Direito à Evolução</td></tr></tbody></table><h2 id="i-contexto-historico-da-declaracao" tabindex="-1">I. Contexto Histórico da Declaração <a class="header-anchor" href="#i-contexto-historico-da-declaracao" aria-label="Permalink to &quot;I. Contexto Histórico da Declaração&quot;">​</a></h2><p>Na longa história do Cosmos Original dos Dez Mil Espíritos e da Âncora Equilibrada (adiante designado por &quot;Heng Yuan Zhou&quot;), o sistema de cultivo predatório dominou durante muito tempo a ordem cósmica. Os fortes usavam a devoração da origem, da sorte e da energia vital dos fracos como degrau para o seu avanço; as seitas usavam o monopólio dos métodos de cultivo como base para o domínio; e os planos usavam a guerra e a escravidão como caminho para a expansão. Este sistema gerou, a curto prazo, algumas poucas potências supremas, mas a longo prazo esgotou o potencial evolutivo do cosmos, causando frequentes ruturas civilizacionais, o definhar das Dez Mil Raças e a aceleração do aumento da entropia cósmica.</p><p>O nascimento da Civilização Simbiótica da Âncora é uma resposta fundamental a este impasse histórico. A presente declaração proclama: a era do sistema de cultivo predatório chegou ao fim, e uma nova era de evolução simbiótica teve início. Todos os seres em Heng Yuan Zhou, independentemente de raça, forma ou nível de cultivo, gozam de igual direito à evolução.</p><h2 id="ii-reivindicacoes-centrais-da-declaracao" tabindex="-1">II. Reivindicações Centrais da Declaração <a class="header-anchor" href="#ii-reivindicacoes-centrais-da-declaracao" aria-label="Permalink to &quot;II. Reivindicações Centrais da Declaração&quot;">​</a></h2><p>A presente declaração estabelece as seguintes reivindicações centrais inabaláveis:</p><ol><li><strong>Igualdade do Direito à Evolução</strong>: cada ser tem o direito fundamental de escolher o seu próprio caminho evolutivo, e nenhuma organização ou indivíduo pode privar ou limitar este direito por qualquer motivo.</li><li><strong>Princípio Anti-Predatório</strong>: é proibido cultivar através da devoração, escravidão ou exploração da origem ou energia de outros seres; toda a evolução deve assentar na base do ciclo simbiótico.</li><li><strong>Abertura dos Sistemas</strong>: os Trezentos Sistemas de Cultivo da Origem estão gratuitamente abertos às Dez Mil Raças, e os métodos de cultivo deixam de ser propriedade privada de poucos.</li><li><strong>Mais Trabalho, Mais Recompensa</strong>: os resultados evolutivos correspondem ao esforço individual; opõe-se tanto à distribuição predatória sem esforço como à distribuição preguiçosa do igualitarismo.</li><li><strong>Crescimento Autónomo</strong>: respeita-se o ritmo evolutivo autónomo de cada ser; não se força nem se apressa o crescimento, oferecendo-se simultaneamente o apoio ambiental e de recursos necessário.</li><li><strong>Um Caminho para Todos</strong>: garante-se que cada ser encontra um caminho de cultivo adequado às suas características; não existe nenhum indivíduo abandonado pelo sistema evolutivo.</li><li><strong>Progresso Conjunto das Dez Mil Raças</strong>: a evolução não é um jogo de soma zero; a cooperação e a simbiose entre as Dez Mil Raças podem gerar uma eficácia evolutiva coletiva superior à soma dos indivíduos.</li></ol><h2 id="iii-base-juridica-da-declaracao" tabindex="-1">III. Base Jurídica da Declaração <a class="header-anchor" href="#iii-base-juridica-da-declaracao" aria-label="Permalink to &quot;III. Base Jurídica da Declaração&quot;">​</a></h2><p>A presente declaração não é um apelo moral vazio, mas um programa civilizacional com sólida base jurídica. A sua base jurídica inclui:</p><table tabindex="0"><thead><tr><th>Nível Jurídico</th><th>Base</th><th>Explicação</th></tr></thead><tbody><tr><td>Nível das Leis Cósmicas</td><td>Lei da Simbiose da Origem</td><td>a própria lei da origem cósmica tende para a simbiose ordenada e não para a predação desordenada; o mecanismo de Ponto de Âncora é a manifestação desta lei</td></tr><tr><td>Nível da Constituição Civilizacional</td><td>Constituição da Civilização Simbiótica</td><td>a presente declaração é o precursor espiritual da constituição; a constituição concretiza as reivindicações da declaração em normas jurídicas executórias</td></tr><tr><td>Nível da Garantia Mecanística</td><td>Contrato Vinculado à Produção e Rede de Pontos de Âncora</td><td>através do desenho institucional, garante-se que as reivindicações da declaração não sejam esvaziadas; o direito à evolução de cada ser tem suporte substantivo de recursos e mecanismos</td></tr></tbody></table><h2 id="iv-apelo-da-declaracao-as-dez-mil-racas" tabindex="-1">IV. Apelo da Declaração às Dez Mil Raças <a class="header-anchor" href="#iv-apelo-da-declaracao-as-dez-mil-racas" aria-label="Permalink to &quot;IV. Apelo da Declaração às Dez Mil Raças&quot;">​</a></h2><p>A presente declaração lança um apelo a todas as raças e formas de vida em Heng Yuan Zhou:</p><ul><li>abandonar o antigo caminho do cultivo predatório e juntar-se ao novo sistema de evolução simbiótica</li><li>abrir os conhecimentos e recursos de cultivo que detêm, participando na co-construção e otimização dos Trezentos Sistemas</li><li>respeitar o direito de escolha evolutiva das outras raças, não impondo os seus próprios padrões aos outros</li><li>participar ativamente na construção e manutenção da rede de pontos de âncora, contribuindo para a ascensão dimensional de todo o cosmos</li><li>manter os limites éticos durante a evolução, não recuperando comportamentos predatórios sob qualquer pretexto</li></ul><h2 id="v-eficacia-e-revisao-da-declaracao" tabindex="-1">V. Eficácia e Revisão da Declaração <a class="header-anchor" href="#v-eficacia-e-revisao-da-declaracao" aria-label="Permalink to &quot;V. Eficácia e Revisão da Declaração&quot;">​</a></h2><p>A presente declaração entra em vigor a partir da data de fundação da Civilização Simbiótica da Âncora, sendo o programa espiritual supremo de todas as instituições civilizacionais em Heng Yuan Zhou. A revisão da declaração requer uma maioria de dois terços do Parlamento da República das Dez Mil Raças, e não pode contrariar o espírito central de &quot;anti-predação, promoção da simbiose&quot;. Quaisquer leis, instituições ou métodos de cultivo que contrariem o espírito da presente declaração são nulos.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A Declaração da Civilização Simbiótica da Âncora é o primeiro programa civilizacional na história de Heng Yuan Zhou que tem a &quot;simbiose&quot; como núcleo e o &quot;progresso conjunto das Dez Mil Raças&quot; como objetivo. Proclama o fim de uma velha era e o início de uma nova. Sob a orientação da declaração, Heng Yuan Zhou caminhará para a direção última da simbiose das Dez Mil Raças e da ascensão dimensional do cosmos.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Visão Geral do Cosmos de Heng Yuan Zhou)</li><li>03-共生文明宪章 (Constituição da Civilização Simbiótica)</li><li>04-反掠夺主义核心论纲 (Teses Centrais do Anti-Predacionismo)</li></ul>',20)])])}const v=o(t,[["render",s]]);export{p as __pageData,v as default};
